import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import { StatusBar, BottomNav } from '../components/Layout';
import { FormSheet, SuccessSheet, ConfirmDialog } from '../components/Sheets';

const products = [
  { id:1, name:'Modern Architecture Textbook', cat:'Books', price:'₹450', badge:'available', img:'https://images.unsplash.com/photo-1507842217343-583bb7270b66?w=400&q=80', seller:'Meera R.', rating:4.8, desc:'Comprehensive architecture reference in perfect condition. No highlights or annotations. Ideal for 4th year students.' },
  { id:2, name:'TI-84 Plus Calculator', cat:'Tech', price:'₹820', badge:'available', img:'https://images.unsplash.com/photo-1611532736597-de2d4265fba3?w=400&q=80', seller:'Nikhil V.', rating:4.6, desc:'Scientific graphing calculator, comes with fresh batteries and the original manual.' },
  { id:3, name:'Cannondale Mountain Bike', cat:'Transport', price:'₹3,100', badge:'sold', img:'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=400&q=80', seller:'Arav S.', rating:5.0, desc:'21-speed mountain bike, recently serviced. Minor scuffs on the frame.' },
  { id:4, name:'Mechanical Keyboard (TKL)', cat:'Tech', price:'₹1,200', badge:'available', img:'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?w=400&q=80', seller:'Sana K.', rating:4.7, desc:'Keychron K8 with brown switches. Comes with USB-C cable. Light use, excellent condition.' },
  { id:5, name:'IKEA Foldable Desk', cat:'Furniture', price:'₹600', badge:'reserved', img:'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=400&q=80', seller:'Yash D.', rating:4.5, desc:'Compact fold-up desk, ideal for dorm rooms. Easy assembly included.' },
  { id:6, name:"Levi's Denim Jacket (M)", cat:'Clothing', price:'₹750', badge:'available', img:'https://images.unsplash.com/photo-1523381210434-271e8be1f52b?w=400&q=80', seller:'Pooja N.', rating:4.9, desc:'Classic vintage look, worn 3-4 times. Dry cleaned and ready.' },
];

const categories = ['All', 'Tech', 'Books', 'Clothing', 'Transport', 'Furniture'];

const badgeColors = {
  available: { bg:'var(--teal-l)', color:'var(--teal)' },
  sold: { bg:'var(--s2)', color:'var(--ink3)' },
  reserved: { bg:'var(--amber-l)', color:'var(--amber)' },
};

const listFields = [
  { key:'title', label:'Item Name', placeholder:'e.g. Physics Textbook Vol. 2', required:true },
  { key:'category', label:'Category', type:'select', options:['Tech', 'Books', 'Clothing', 'Transport', 'Furniture', 'Sports', 'Other'], required:true },
  { key:'price', label:'Price (₹)', type:'number', placeholder:'e.g. 450', required:true },
  { key:'condition', label:'Condition', type:'select', options:['Like New', 'Good', 'Fair', 'Needs Repair'], required:true },
  { key:'description', label:'Description', type:'textarea', placeholder:'Describe the item, any defects…', required:true },
  { key:'contact', label:'Contact Number', placeholder:'+91 99999 99999', required:true },
];

function DetailSheet({ item, onClose }) {
  const [step, setStep] = useState('view'); // 'view' | 'confirm' | 'success'

  if (step === 'success') {
    return (
      <div style={{ position:'absolute', inset:0, background:'rgba(0,0,0,.5)', backdropFilter:'blur(6px)', zIndex:300, display:'flex', alignItems:'flex-end' }}>
        <div style={{ background:'var(--surface)', width:'100%', borderRadius:'22px 22px 0 0', padding:'32px 24px 36px', animation:'slideUp .38s cubic-bezier(.34,1.2,.64,1) both', textAlign:'center' }}>
          <div style={{ fontSize:56, marginBottom:14, animation:'bounceIn .5s cubic-bezier(.34,1.4,.64,1) both' }}>🎉</div>
          <div style={{ fontFamily:'Syne', fontWeight:800, fontSize:21, color:'var(--ink)', marginBottom:8 }}>Purchase Requested!</div>
          <div style={{ fontFamily:'DM Sans', fontSize:13, color:'var(--ink3)', lineHeight:1.6, marginBottom:22 }}>
            Your request for <strong style={{ color:'var(--ink)' }}>{item.name}</strong> has been sent to <strong style={{ color:'var(--navy)' }}>{item.seller}</strong>. They'll confirm within 24h.
          </div>
          <button onClick={onClose} style={{ width:'100%', padding:'14px 0', borderRadius:10, border:'none', background:'linear-gradient(135deg, var(--navy), var(--navy2))', color:'#fff', fontFamily:'Syne', fontWeight:700, fontSize:14, cursor:'pointer' }}>
            Back to Marketplace
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ position:'absolute', inset:0, background:'rgba(0,0,0,.5)', backdropFilter:'blur(6px)', zIndex:300, display:'flex', alignItems:'flex-end' }}
      onClick={() => { if (step === 'view') onClose(); }}>
      <div style={{ background:'var(--surface)', width:'100%', borderRadius:'22px 22px 0 0', animation:'slideUp .38s cubic-bezier(.34,1.2,.64,1) both', maxHeight:'80%', overflowY:'auto' }}
        onClick={e => e.stopPropagation()}>
        <div style={{ width:32, height:3, background:'var(--s2)', borderRadius:2, margin:'14px auto 0' }} />
        {step === 'confirm' ? (
          <div style={{ padding:'20px 20px 32px', textAlign:'center' }}>
            <div style={{ fontSize:40, marginBottom:12 }}>🛒</div>
            <div style={{ fontFamily:'Syne', fontWeight:800, fontSize:19, color:'var(--ink)', marginBottom:8 }}>Confirm Purchase?</div>
            <div style={{ fontFamily:'DM Sans', fontSize:13, color:'var(--ink3)', marginBottom:6 }}>{item.name}</div>
            <div style={{ fontFamily:'Syne', fontWeight:800, fontSize:26, color:'var(--amber)', marginBottom:20 }}>{item.price}</div>
            <div style={{ background:'var(--s2)', borderRadius:10, padding:'12px 14px', fontSize:12, color:'var(--ink3)', fontFamily:'DM Sans', marginBottom:22, lineHeight:1.6 }}>
              This sends a <strong>purchase request</strong> to {item.seller}. Payment is done in person on handover.
            </div>
            <div style={{ display:'flex', gap:10 }}>
              <button onClick={() => setStep('view')} style={{ flex:1, padding:'13px 0', borderRadius:9, border:'1px solid var(--s2)', background:'transparent', fontFamily:'Syne', fontWeight:700, fontSize:13, color:'var(--ink)', cursor:'pointer' }}>Cancel</button>
              <button onClick={() => setStep('success')} style={{ flex:1.5, padding:'13px 0', borderRadius:9, border:'none', background:'linear-gradient(135deg, var(--navy), var(--navy2))', color:'#fff', fontFamily:'Syne', fontWeight:700, fontSize:13, cursor:'pointer' }}>Confirm →</button>
            </div>
          </div>
        ) : (
          <>
            <div style={{ borderRadius:16, overflow:'hidden', margin:'16px 20px 0', height:180 }}>
              <img src={item.img} alt={item.name} style={{ width:'100%', height:'100%', objectFit:'cover' }} />
            </div>
            <div style={{ padding:'16px 20px 28px' }}>
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8 }}>
                <h2 style={{ fontFamily:'Syne', fontWeight:800, fontSize:19, color:'var(--ink)', flex:1, marginRight:12 }}>{item.name}</h2>
                <span style={{ padding:'3px 9px', borderRadius:4, fontSize:10, fontFamily:'Syne', fontWeight:700, textTransform:'uppercase', background: badgeColors[item.badge]?.bg, color: badgeColors[item.badge]?.color, flexShrink:0 }}>{item.badge}</span>
              </div>
              <p style={{ fontFamily:'DM Sans', fontSize:13, color:'var(--ink2)', marginBottom:10 }}>by {item.seller} &nbsp;·&nbsp; ⭐ {item.rating}</p>
              <div style={{ background:'var(--s2)', borderRadius:10, padding:'11px 13px', marginBottom:14 }}>
                <p style={{ fontFamily:'DM Sans', fontSize:13, color:'var(--ink)', lineHeight:1.6 }}>{item.desc}</p>
              </div>
              <p style={{ fontFamily:'Syne', fontWeight:800, fontSize:24, color:'var(--amber)', marginBottom:18 }}>{item.price}</p>
              <div style={{ display:'flex', gap:10 }}>
                <button onClick={onClose} style={{ flex:1, padding:'13px 0', borderRadius:9, border:'1px solid var(--s2)', background:'transparent', fontFamily:'Syne', fontWeight:700, fontSize:13, color:'var(--ink)', cursor:'pointer' }}>
                  💬 Message
                </button>
                <button
                  disabled={item.badge !== 'available'}
                  onClick={() => item.badge === 'available' && setStep('confirm')}
                  style={{ flex:1.5, padding:'13px 0', borderRadius:9, border:'none', background: item.badge === 'available' ? 'linear-gradient(135deg, var(--navy), var(--navy2))' : 'var(--s2)', color: item.badge === 'available' ? '#fff' : 'var(--ink3)', fontFamily:'Syne', fontWeight:700, fontSize:13, cursor: item.badge === 'available' ? 'pointer' : 'default' }}>
                  {item.badge === 'sold' ? 'Sold Out' : item.badge === 'reserved' ? 'Reserved' : 'Buy Now →'}
                </button>
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

export default function Marketplace() {
  const location = useLocation();
  const urlParams = new URLSearchParams(location.search);
  const initialSearch = urlParams.get('q') || '';
  const shouldList = urlParams.get('list') === '1';

  const [activeCat, setActiveCat] = useState('All');
  const [search, setSearch] = useState(initialSearch);
  const [selected, setSelected] = useState(null);
  const [showList, setShowList] = useState(shouldList);

  const filtered = products.filter(p =>
    (activeCat === 'All' || p.cat === activeCat) &&
    p.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={{ display:'flex', flexDirection:'column', height:'100%', background:'var(--bg)', position:'relative' }}>
      <div style={{ background:'var(--surface)', flexShrink:0, borderBottom:'1px solid var(--s2)' }}>
        <StatusBar />
        <div style={{ padding:'2px 16px 12px' }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:12 }}>
            <h1 style={{ fontFamily:'Syne', fontWeight:800, fontSize:22, color:'var(--ink)' }}>Marketplace</h1>
            <button onClick={() => setShowList(true)} style={{ padding:'8px 14px', borderRadius:9, background:'var(--navy)', color:'#fff', border:'none', fontFamily:'Syne', fontWeight:700, fontSize:12, cursor:'pointer', transition:'transform .15s' }}
              onMouseEnter={e => e.currentTarget.style.transform='scale(1.04)'}
              onMouseLeave={e => e.currentTarget.style.transform=''}
            >+ List</button>
          </div>
          <div style={{ position:'relative', marginBottom:12 }}>
            <div style={{ position:'absolute', left:12, top:'50%', transform:'translateY(-50%)', fontSize:14, opacity:.35 }}>🔍</div>
            <input className="input" placeholder="Search items…" value={search} onChange={e => setSearch(e.target.value)} style={{ paddingLeft:36 }} />
            {search && <button onClick={() => setSearch('')} style={{ position:'absolute', right:10, top:'50%', transform:'translateY(-50%)', border:'none', background:'transparent', cursor:'pointer', color:'var(--ink3)', fontSize:16 }}>✕</button>}
          </div>
          <div style={{ display:'flex', gap:7, overflowX:'auto', paddingBottom:4 }}>
            {categories.map(c => (
              <button key={c} onClick={() => setActiveCat(c)} style={{ padding:'5px 12px', borderRadius:6, border:`1px solid ${activeCat===c ? 'var(--ink)' : 'var(--s2)'}`, fontFamily:'Syne', fontWeight:700, fontSize:10, textTransform:'uppercase', background: activeCat===c ? 'var(--ink)' : 'transparent', color: activeCat===c ? 'var(--bg)' : 'var(--ink3)', whiteSpace:'nowrap', cursor:'pointer', transition:'all .18s' }}>{c}</button>
            ))}
          </div>
        </div>
      </div>

      <div style={{ flex:1, overflowY:'auto', padding:'14px 16px 90px' }}>
        {search && <p style={{ fontFamily:'DM Sans', fontSize:12, color:'var(--ink3)', marginBottom:12 }}>Showing {filtered.length} results for "<strong>{search}</strong>"</p>}
        <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
          {filtered.map((item, i) => (
            <div key={item.id} onClick={() => setSelected(item)}
              style={{ background:'var(--surface)', borderRadius:14, overflow:'hidden', boxShadow:'var(--sh)', cursor:'pointer', animation:`scaleIn .38s ease ${i * .06}s both`, transition:'transform .2s, box-shadow .2s' }}
              onMouseEnter={e => { e.currentTarget.style.transform='translateY(-3px)'; e.currentTarget.style.boxShadow='var(--shm)'; }}
              onMouseLeave={e => { e.currentTarget.style.transform=''; e.currentTarget.style.boxShadow='var(--sh)'; }}
            >
              <div style={{ height:120, overflow:'hidden', position:'relative' }}>
                <img src={item.img} alt={item.name} style={{ width:'100%', height:'100%', objectFit:'cover', transition:'transform .5s' }}
                  onMouseEnter={e => e.target.style.transform='scale(1.1)'}
                  onMouseLeave={e => e.target.style.transform='scale(1)'}
                />
                <div style={{ position:'absolute', top:8, left:8, padding:'3px 8px', borderRadius:4, fontSize:9.5, fontFamily:'Syne', fontWeight:700, textTransform:'uppercase', background: badgeColors[item.badge]?.bg, color: badgeColors[item.badge]?.color }}>
                  {item.badge}
                </div>
              </div>
              <div style={{ padding:'11px 12px' }}>
                <div style={{ fontFamily:'DM Sans', fontWeight:600, fontSize:12.5, color:'var(--ink)', marginBottom:4, lineHeight:1.3 }}>{item.name}</div>
                <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:4 }}>
                  <span style={{ fontFamily:'Syne', fontWeight:800, fontSize:15, color:'var(--amber)' }}>{item.price}</span>
                  <span style={{ fontSize:10.5, color:'var(--ink3)', fontFamily:'DM Sans' }}>⭐ {item.rating}</span>
                </div>
                <div style={{ fontSize:10.5, color:'var(--ink3)', fontFamily:'DM Sans', marginBottom:9 }}>by {item.seller}</div>
                <button
                  disabled={item.badge !== 'available'}
                  onClick={e => { e.stopPropagation(); setSelected(item); }}
                  style={{ width:'100%', padding:'8px 0', borderRadius:8, border:'none', cursor: item.badge === 'available' ? 'pointer' : 'default', fontFamily:'Syne', fontWeight:700, fontSize:11.5, textTransform:'uppercase', letterSpacing:'.04em', background: item.badge === 'available' ? 'var(--navy)' : 'var(--s2)', color: item.badge === 'available' ? '#fff' : 'var(--ink3)', transition:'transform .15s' }}
                  onMouseEnter={e => { if (item.badge === 'available') e.currentTarget.style.transform='scale(1.02)'; }}
                  onMouseLeave={e => e.currentTarget.style.transform=''}
                >{item.badge === 'sold' ? 'Sold Out' : item.badge === 'reserved' ? 'Reserved' : 'Buy Now'}</button>
              </div>
            </div>
          ))}
        </div>
        {filtered.length === 0 && (
          <div style={{ textAlign:'center', color:'var(--ink3)', paddingTop:60 }}>
            <div style={{ fontSize:40, marginBottom:8 }}>🛍️</div>
            <p style={{ fontFamily:'Syne', fontWeight:700, fontSize:14 }}>Nothing found</p>
            <p style={{ fontSize:12, marginTop:4 }}>Try a different search or category</p>
          </div>
        )}
      </div>

      {selected && <DetailSheet item={selected} onClose={() => setSelected(null)} />}
      {showList && <FormSheet title="📦 List an Item" fields={listFields} submitLabel="Publish Listing" onClose={() => setShowList(false)} />}

      <BottomNav />
    </div>
  );
}
